 import { supabase } from '../lib/supabase'

const PAYFAST_MERCHANT_ID = '36412593'
const PAYFAST_MERCHANT_KEY = 'zljtf3msm3wht'
const MODE = 'sandbox'

const PAYFAST_URL = MODE === 'sandbox' 
    ? 'https://sandbox.payfast.co.za/eng/process'
    : 'https://www.payfast.co.za/eng/process'

// Generate unique reference
function generateReference(communityId, userId) {
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(2, 8)
    return `PF-${communityId.substring(0, 4)}-${userId.substring(0, 4)}-${timestamp}-${random}`
}

// ============================================
// 1. COMMUNITY PAYMENT
// ============================================
export async function initiateCommunityPayment(communityId, userId, amount, itemName) {
    try {
        const { data: payment, error } = await supabase
            .from('subscription_payments')
            .insert({
                community_id: communityId,
                user_id: userId,
                amount: amount,
                platform_fee: amount / 2,
                creator_earnings: amount / 2,
                currency: 'ZAR',
                type: 'community',
                status: 'pending'
            })
            .select()
            .single()

        if (error) throw error

        const payfastData = {
            merchant_id: PAYFAST_MERCHANT_ID,
            merchant_key: PAYFAST_MERCHANT_KEY,
            return_url: window.location.origin + '/payment/success',
            cancel_url: window.location.origin + '/payment/cancel',
            notify_url: window.location.origin + '/payment/success',
            m_payment_id: payment.id,
            amount: amount.toFixed(2),
            item_name: itemName,
            item_description: `Monthly subscription to ${itemName}`,
            custom_str1: communityId,
            custom_str2: userId,
            custom_str3: 'community',
            email_confirmation: '1',
            confirmation_address: 'info@predictfc.com'
        }

        return {
            success: true,
            paymentId: payment.id,
            payfastData: payfastData,
            payfastUrl: PAYFAST_URL
        }
    } catch (error) {
        console.error('Community payment error:', error)
        return { success: false, error: error.message }
    }
}

// ============================================
// 2. GLOBAL PREMIUM SUBSCRIPTION (R40/month)
// ============================================
export async function initiatePremiumSubscription(userId, email) {
    try {
        const amount = 40.00

        const { data: payment, error } = await supabase
            .from('subscription_payments')
            .insert({
                user_id: userId,
                amount: amount,
                platform_fee: amount * 0.05, // 5% platform fee
                creator_earnings: amount * 0.95,
                currency: 'ZAR',
                type: 'premium',
                status: 'pending'
            })
            .select()
            .single()

        if (error) throw error

        const payfastData = {
            merchant_id: PAYFAST_MERCHANT_ID,
            merchant_key: PAYFAST_MERCHANT_KEY,
            return_url: window.location.origin + '/payment/success',
            cancel_url: window.location.origin + '/payment/cancel',
            notify_url: window.location.origin + '/payment/success',
            m_payment_id: payment.id,
            amount: amount.toFixed(2),
            item_name: 'PredictFC Premium Subscription',
            item_description: 'Monthly Premium Subscription to PredictFC',
            custom_str1: userId,
            custom_str2: 'premium',
            custom_str3: 'premium',
            email_confirmation: '1',
            confirmation_address: email || 'info@predictfc.com'
        }

        return {
            success: true,
            paymentId: payment.id,
            payfastData: payfastData,
            payfastUrl: PAYFAST_URL
        }
    } catch (error) {
        console.error('Premium payment error:', error)
        return { success: false, error: error.message }
    }
}

// ============================================
// 3. COMPLETE PAYMENT (Webhook / Callback Handler)
// ============================================
export async function completePayment(paymentId, userId, type, communityId = null) {
    try {
        // Update payment status
        await supabase
            .from('subscription_payments')
            .update({ 
                status: 'success',
                expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() 
            })
            .eq('id', paymentId)

        if (type === 'community' && communityId) {
            // Check if already a member
            const { data: existing } = await supabase
                .from('community_members')
                .select('id')
                .eq('community_id', communityId)
                .eq('user_id', userId)
                .maybeSingle()

            if (!existing) {
                // Add user as member
                await supabase
                    .from('community_members')
                    .insert({
                        community_id: communityId,
                        user_id: userId,
                        role: 'member',
                        status: 'active',
                        expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
                    })

                // Update member count
                const { data: communityData } = await supabase
                    .from('communities')
                    .select('member_count')
                    .eq('id', communityId)
                    .single()

                await supabase
                    .from('communities')
                    .update({
                        member_count: (communityData?.member_count || 0) + 1
                    })
                    .eq('id', communityId)
            }
        }

        return { success: true }
    } catch (error) {
        console.error('Error completing payment:', error)
        return { success: false, error: error.message }
    }
}

// ============================================
// 4. PAYMENT STATUS CHECKER
// ============================================
export async function getPaymentStatus(paymentId) {
    try {
        const { data, error } = await supabase
            .from('subscription_payments')
            .select('*')
            .eq('id', paymentId)
            .single()

        if (error) throw error
        return { success: true, payment: data }
    } catch (error) {
        console.error('Error getting payment status:', error)
        return { success: false, error: error.message }
    }
}
